insert into public.providers
  (id, slug, display_name, headline, bio, category, city, timezone, offers_online, offers_in_person, years_experience, languages, status, photo_url, updated_at)
values
  ('00000000-0000-4000-8000-000000000001', 'anna-yoga', 'Anna Whitfield', 'Vinyasa and yin yoga for people who sit all day', 'I teach from a small studio off Columbia Road in Bethnal Green and online. Most of my students work at a desk: classes are calm and precise, and built around your back, hips and sleep. No handstands required.', 'yoga', 'London', 'Europe/London', true, true, 9, array['English']::text[], 'approved', '/images/providers/anna-yoga.jpg', '2026-10-01T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000002', 'freya-yoga', 'Freya Campbell', 'Yoga for runners and hillwalkers', 'Former Edinburgh Marathon pacer and BWY-qualified teacher. Strong hips, happy hamstrings and better breathing for people who spend their weekends on the Pentlands or the road.', 'yoga', 'Edinburgh', 'Europe/London', true, true, 7, array['English']::text[], 'approved', null, '2026-10-02T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000003', 'olivia-yoga', 'Olivia Bennett', 'Pregnancy and postnatal yoga', 'Specialist pregnancy yoga teacher and doula in Clifton. Gentle, safe practice for every trimester and the months after birth. Babies are welcome at postnatal classes.', 'yoga', 'Bristol', 'Europe/London', false, true, 6, array['English']::text[], 'approved', null, '2026-10-03T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000004', 'hannah-yoga', 'Hannah Price', 'Morning yoga and breathwork online', 'Live sessions to start the day, taught in English or Welsh. One-to-one or with a friend, cameras optional. Twenty minutes is enough to feel the difference.', 'yoga', 'Cardiff', 'Europe/London', true, false, 5, array['English', 'Welsh']::text[], 'approved', null, '2026-10-04T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000005', 'sarah-yoga', 'Sarah Thompson', 'Yoga therapy for back and neck pain', 'Accredited yoga therapist working alongside two Hove physiotherapy clinics. Slow, evidence-informed practice for back, neck and joint pain. Bring your scan results if you have them.', 'yoga', 'Brighton', 'Europe/London', true, true, 11, array['English']::text[], 'approved', null, '2026-10-05T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000006', 'imogen-yoga', 'Imogen Hart', 'Reformer Pilates in a private Clapham studio', 'STOTT-trained Pilates instructor with a two-reformer studio near Clapham Common. Posture, core strength and rehab after injury, with no crowded classes.', 'yoga', 'London', 'Europe/London', false, true, 8, array['English', 'French']::text[], 'approved', null, '2026-10-06T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000007', 'priya-yoga', 'Priya Desai', 'Mat Pilates online for posture and core', 'Physiotherapy graduate teaching mat Pilates online. Short, focused sessions that fit into a lunch break, with clear cues even through a laptop camera.', 'yoga', 'Leeds', 'Europe/London', true, false, 4, array['English', 'Gujarati']::text[], 'approved', null, '2026-10-07T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000008', 'marcus-fitness', 'Marcus Hale', 'Strength training that fits a 3-day week', 'REPs Level 4 coach and former rugby league player. I write simple, progressive strength programmes and teach you to lift with confidence at a private gym in Ancoats.', 'fitness', 'Manchester', 'Europe/London', false, true, 12, array['English']::text[], 'approved', '/images/providers/marcus-fitness.jpg', '2026-10-08T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000009', 'tom-fitness', 'Tom Gallagher', 'Mobility and functional training', 'For people who want to feel strong in everyday life: carrying kids, climbing Munros and getting up off the floor without thinking about it. Sessions in the West End or on video.', 'fitness', 'Glasgow', 'Europe/London', true, true, 5, array['English']::text[], 'approved', null, '2026-10-09T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000010', 'ryan-fitness', 'Ryan Mitchell', 'Online running coach: couch to marathon', 'UK Athletics coach. Personalised training plans, weekly check-ins and form analysis from video. I have coached over 300 runners to their first parkrun, half or London Marathon.', 'fitness', 'Leeds', 'Europe/London', true, false, 8, array['English']::text[], 'approved', null, '2026-10-10T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000011', 'jade-fitness', 'Jade Okoro', 'Boxing fitness and strength for women', 'England Boxing coach and personal trainer in Peckham. Pad work, strength and conditioning in a friendly private space. No experience needed and no sparring unless you want it.', 'fitness', 'London', 'Europe/London', false, true, 9, array['English', 'Yoruba']::text[], 'approved', null, '2026-10-11T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000012', 'callum-fitness', 'Callum Fraser', 'Hyrox and conditioning coaching', 'Hyrox Elite 15 finisher coaching first-timers and age-groupers in Leith. Running, sled work and wall balls, with a plan that keeps you injury-free up to race day.', 'fitness', 'Edinburgh', 'Europe/London', false, true, 6, array['English']::text[], 'approved', null, '2026-10-12T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000013', 'leah-fitness', 'Leah Morgan', 'Strength and balance for over-50s', 'Exercise referral specialist working with GPs across Cardiff. Gentle, progressive strength and balance training for bone health, arthritis and confidence on the stairs.', 'fitness', 'Cardiff', 'Europe/London', true, true, 14, array['English', 'Welsh']::text[], 'approved', null, '2026-10-13T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000014', 'danny-fitness', 'Danny Walsh', 'Weight loss training without the faddy diets', 'Personal trainer and qualified nutrition coach in the Baltic Triangle. Realistic training, food you actually like and weekly check-ins that keep you going.', 'fitness', 'Liverpool', 'Europe/London', false, true, 7, array['English']::text[], 'approved', null, '2026-10-14T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000015', 'sophie-tutoring', 'Sophie Turner', 'GCSE and A-level maths and physics', 'Imperial College PhD student in applied physics. I explain the why behind every formula, so exams stop being about memorising. AQA, Edexcel and OCR specifications.', 'tutoring', 'London', 'Europe/London', true, false, 6, array['English']::text[], 'approved', null, '2026-10-15T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000016', 'ravi-tutoring', 'Ravi Patel', '11+ preparation for grammar school entry', 'Former primary teacher in Solihull. Verbal and non-verbal reasoning, maths and English for the GL and CEM 11+ papers. Calm, structured and never cramming.', 'tutoring', 'Birmingham', 'Europe/London', true, true, 12, array['English', 'Gujarati']::text[], 'approved', null, '2026-10-01T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000017', 'eleanor-tutoring', 'Eleanor Wright', 'Oxbridge English applications and interviews', 'Oxford English graduate and former admissions interviewer. Personal statements, the ELAT and mock interviews that feel like the real thing, without the panic.', 'tutoring', 'Oxford', 'Europe/London', true, false, 10, array['English', 'French']::text[], 'approved', null, '2026-10-02T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000018', 'owen-tutoring', 'Owen Davies', 'Welsh lessons and GCSE Welsh', 'Learn Welsh with a first-language speaker: GCSE and A-level Welsh, or conversational Welsh for adults who have just moved to Wales. Dysgu Cymraeg, step by step.', 'tutoring', 'Cardiff', 'Europe/London', true, false, 8, array['English', 'Welsh']::text[], 'approved', null, '2026-10-03T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000019', 'hamza-tutoring', 'Hamza Ali', 'Programming tutor: Python, JavaScript and GCSE computer science', 'Software engineer at a Manchester fintech. I teach programming through small projects you actually want to build, and GCSE computer science for OCR and AQA.', 'tutoring', 'Manchester', 'Europe/London', true, false, 4, array['English', 'Urdu']::text[], 'approved', null, '2026-10-04T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000020', 'grace-tutoring', 'Grace O''Neill', 'A-level chemistry and biology', 'Queen''s University graduate and secondary science teacher. Organic chemistry that finally makes sense, required practicals and exam technique for CCEA, AQA and OCR.', 'tutoring', 'Belfast', 'Europe/London', true, false, 7, array['English', 'Irish']::text[], 'approved', null, '2026-10-05T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000021', 'lucy-tutoring', 'Lucy Chambers', 'Reading, KS2 SATs and dyslexia support', 'Qualified SENCo with 15 years in Bristol primary schools. Phonics, reading confidence and SATs preparation, with a specialist approach for dyslexic children.', 'tutoring', 'Bristol', 'Europe/London', true, true, 15, array['English']::text[], 'approved', null, '2026-10-06T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000022', 'isabel-tutoring', 'Isabel Romero', 'Spanish for GCSE, A-level and adults', 'Native speaker from Seville, living in Hackney. Exam-focused lessons for students and conversation-first lessons for adults planning a move or a long holiday.', 'tutoring', 'London', 'Europe/London', true, false, 5, array['English', 'Spanish']::text[], 'approved', null, '2026-10-07T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000023', 'kwame-tutoring', 'Kwame Mensah', 'A-level economics and university admissions', 'LSE economics graduate now working as an analyst. Clear diagrams, real-world examples and essay structure that gets the evaluation marks.', 'tutoring', 'Leeds', 'Europe/London', true, false, 3, array['English', 'Twi']::text[], 'approved', null, '2026-10-08T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000024', 'emma-coaching', 'Emma Clarke', 'Career change coaching', 'I changed careers twice: from law to UX research to coaching. Together we turn a vague ''I want something else'' into a concrete plan. Sessions in Farringdon or on video.', 'coaching', 'London', 'Europe/London', true, true, 10, array['English', 'French']::text[], 'approved', '/images/providers/emma-coaching.jpg', '2026-10-09T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000025', 'james-coaching', 'James Okafor', 'Leadership coaching for first-time managers', 'Ex-engineering director at two London scale-ups. I coach new managers through feedback, delegation and the awkward first year of leading former peers.', 'coaching', 'London', 'Europe/London', true, false, 15, array['English']::text[], 'approved', null, '2026-10-10T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000026', 'aisha-coaching', 'Aisha Rahman', 'ADHD and productivity coaching', 'ICF-accredited coach with ADHD myself. Practical systems for focus, planning and follow-through that work with your brain, not against it. Access to Work funding accepted.', 'coaching', 'Birmingham', 'Europe/London', true, false, 9, array['English', 'Urdu']::text[], 'approved', null, '2026-10-11T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000027', 'fiona-coaching', 'Fiona MacLeod', 'Executive coaching for senior leaders', 'Former FTSE 250 HR director. Confidential coaching for directors and new board members: influence, difficult decisions and finding a sustainable pace.', 'coaching', 'Glasgow', 'Europe/London', true, false, 18, array['English', 'Scottish Gaelic']::text[], 'approved', null, '2026-10-12T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000028', 'ben-coaching', 'Ben Harrington', 'Founder and startup coaching', 'Two-time founder, one exit. I coach early-stage founders on fundraising, hiring the first team and not burning out on the way.', 'coaching', 'Bristol', 'Europe/London', true, false, 12, array['English']::text[], 'approved', null, '2026-10-13T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000029', 'nadia-coaching', 'Nadia Hussain', 'Graduate job and interview coaching', 'Former graduate recruiter at a Big Four firm. CVs, assessment centres and competency interviews, so your first job search is shorter and less stressful.', 'coaching', 'Manchester', 'Europe/London', true, false, 6, array['English', 'Arabic']::text[], 'approved', null, '2026-10-14T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000030', 'chris-coaching', 'Chris Lawson', 'Public speaking and confidence coaching', 'Former BBC Radio Newcastle presenter. Calm nerves, clear structure and a voice people listen to, whether it is a best man''s speech or a conference keynote.', 'coaching', 'Newcastle', 'Europe/London', true, true, 11, array['English']::text[], 'approved', null, '2026-10-15T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000031', 'megan-massage', 'Megan Hughes', 'Sports and deep tissue massage', 'Graduate sports therapist working with runners and cyclists from her Headingley clinic. Deep tissue work with mobility advice you can use at home.', 'massage', 'Leeds', 'Europe/London', false, true, 8, array['English']::text[], 'approved', null, '2026-10-01T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000032', 'chloe-massage', 'Chloe Barnes', 'Pregnancy and relaxation massage', 'Over a decade in spa and clinical settings in Kemptown. Quiet, unhurried sessions for stress relief, with a specialist pregnancy couch from 12 weeks.', 'massage', 'Brighton', 'Europe/London', false, true, 13, array['English']::text[], 'approved', null, '2026-10-02T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000033', 'siobhan-massage', 'Siobhan Kelly', 'Thai and myofascial massage', 'Trained in Chiang Mai and Manchester. Sessions blend assisted stretching and slow pressure work to release tension and improve range of motion. Northern Quarter studio.', 'massage', 'Manchester', 'Europe/London', false, true, 6, array['English']::text[], 'approved', null, '2026-10-03T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000034', 'arjun-massage', 'Arjun Mehta', 'Sports massage and injury rehab', 'Soft tissue therapist working with amateur football and rugby clubs in south London. Treatment, taping and a rehab plan, from a clinic near Clapham Junction.', 'massage', 'London', 'Europe/London', false, true, 10, array['English', 'Hindi']::text[], 'approved', null, '2026-10-04T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000035', 'rachel-massage', 'Rachel Adams', 'Swedish and hot stone massage', 'A calm treatment room in Stockbridge. Classic Swedish and hot stone massage for winter stiffness and stress, with time to sit with a cup of tea afterwards.', 'massage', 'Edinburgh', 'Europe/London', false, true, 9, array['English']::text[], 'approved', null, '2026-10-05T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000036', 'daniel-music', 'Daniel Brooks', 'Piano lessons for adult beginners', 'Jazz pianist and patient teacher in Islington. Adults learn differently from children: my lessons focus on playing real music from week one, with ABRSM grades only if you want them.', 'music', 'London', 'Europe/London', true, true, 14, array['English']::text[], 'approved', null, '2026-10-06T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000037', 'jamie-music', 'Jamie Fletcher', 'Guitar lessons: acoustic and electric', 'Session guitarist and LIPA graduate. Beginners welcome: we start with songs you love, from the Beatles to Oasis to Phoebe Bridgers, and build technique along the way.', 'music', 'Liverpool', 'Europe/London', true, true, 11, array['English']::text[], 'approved', null, '2026-10-07T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000038', 'harriet-music', 'Harriet Cole', 'Violin lessons and ABRSM grades', 'Royal Academy of Music graduate and orchestral player. Structured lessons with clear goals, from first scales to Grade 8 and music college auditions.', 'music', 'Cambridge', 'Europe/London', false, true, 16, array['English', 'German']::text[], 'approved', null, '2026-10-08T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000039', 'ella-music', 'Ella Jenkins', 'Singing lessons and vocal technique', 'Professional singer and choir director. Breath, pitch and confidence for shower singers, choir members and musical theatre auditions.', 'music', 'Cardiff', 'Europe/London', true, true, 7, array['English', 'Welsh']::text[], 'approved', null, '2026-10-09T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000040', 'rhys-music', 'Rhys Evans', 'Music production with Ableton Live', 'Producer and DJ with releases on Manchester labels. Screen-share lessons on arrangement, sound design and mixing, working on your own tracks.', 'music', 'Manchester', 'Europe/London', true, false, 6, array['English']::text[], 'approved', null, '2026-10-10T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000041', 'kofi-music', 'Kofi Asante', 'Drum lessons for all ages', 'Touring drummer with a soundproofed studio in Digbeth. Rock, funk and gospel grooves, Rockschool and Trinity grades, and sticks for everyone.', 'music', 'Birmingham', 'Europe/London', false, true, 9, array['English']::text[], 'approved', null, '2026-10-11T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000042', 'alice-music', 'Alice Wong', 'Music theory and ABRSM Grade 5 theory', 'University of Edinburgh music graduate. Theory that makes sense at the keyboard, for students who need Grade 5 theory to move on to higher practical grades.', 'music', 'Edinburgh', 'Europe/London', true, false, 5, array['English', 'Cantonese']::text[], 'approved', null, '2026-10-12T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000043', 'zoe-coaching', 'Zoe Patterson', 'Wellbeing coaching for new parents', 'Application under review: coaching for parents returning to work after parental leave.', 'coaching', 'London', 'Europe/London', true, false, 2, array['English']::text[], 'pending', null, '2026-10-13T09:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000044', 'gary-fitness', 'Gary Holt', 'Bootcamp training', 'This profile was suspended by an admin.', 'fitness', 'Liverpool', 'Europe/London', false, true, 2, array['English']::text[], 'suspended', null, '2026-10-14T09:00:00.000Z')
